/*
 * string.c — Minimal string/memory functions for bare-metal benchmarks
 *
 * strcpy/strcmp: used by Dhrystone inside the measurement loop
 * (performance-critical).
 * memcpy: generated by the compiler for struct assignments.
 */

char *strcpy(char *dst, const char *src) {
    char *d = dst;
    while ((*d++ = *src++) != '\0')
        ;
    return dst;
}

int strcmp(const char *a, const char *b) {
    while (*a && *a == *b) {
        a++;
        b++;
    }
    return (unsigned char)*a - (unsigned char)*b;
}

void *memcpy(void *dst, const void *src, unsigned long n) {
    char *d = dst;
    const char *s = src;
    while (n--)
        *d++ = *s++;
    return dst;
}
